import { loadFont as loadSans } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadSerif } from "@remotion/google-fonts/Cinzel";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// PASTOR EVANDRO — Igreja Evangélica Missões Brasa Viva (Inocência), cliente do Leonardo — chamada "oração", 26/10.
// Pedido do Leonardo: o pastor só tem um take e o culto não tem imagem bonita, então "não pode ser pegada fraca":
// motion contando a fala (oração, família, casa, alguém em crise), escrito bonito na tela, as fotos dos pastores e da
// fachada "misturadas" na fala, trilha evangélica forte. Identidade da Brasa Viva já usada no convite de 23/10
// (vermelho do "VIVA", grafite, dourado da chama, Cinzel como no logo), com entradas e cenas próprias deste vídeo.
// Pictogramas desenhados (traço grosso e redondo) no lugar de banco de imagens: problema em visual genérico, igreja só
// na solução. Botão de CTA nos 15 s do começo e de novo no "clique no link" (padrão do cliente).
// v3 (o diretor): cena da crise trocada por tempestade sobre a casa; música um pouco mais baixa (som em tools/audio3.py).
// v2 (o diretor): música do cliente (What A Beautiful Name, em edit/), voz sem falhas — cada take inteiro, sem corte dentro
// (aroll2.mp4) —, música e efeitos mais baixos, mais criações de motion e nada "chacoalhando": sem socos de zoom, sem
// tremida na crise; a câmera passa de um plano a outro deslizando. Os tempos abaixo continuam na régua da v1 (palavra a
// palavra) e são convertidos pela tabela OLD_SEGS/NEW_TAKES (cada início de frase da v1 = mesmo ponto do take na v2).

const { fontFamily: F } = loadSans("normal", { weights: ["600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: S } = loadSerif("normal", { weights: ["700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const PE_FPS = 30;
const SPEECH = 66.9667; // fim da fala na régua da v1
const SPEECH2 = 71.2; // fim da fala na v2 (takes inteiros)
const END = 64.9; // cartão final ("Esperamos por vocês"), régua da v1
const OLD_DUR = SPEECH + 1.8;
export const PE_DUR = SPEECH2 + 1.8;
export const PE_FRAMES = Math.round(PE_DUR * PE_FPS);
const R = "#B3141C";
const GOLD = "#E2A845";
const BK = "#121212";
const NIGHT = "#14161B";
const CREAM = "#F5EFE6";
const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.bezier(0.2, 0.9, 0.3, 1); // assenta sem passar do ponto
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const ease = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const SHADOW = "0 4px 22px rgba(0,0,0,0.75), 0 0 4px rgba(0,0,0,0.5)";
const P = (f: string) => staticFile(`pastor-evandro/${f}`);

// régua da v1 (edit/cortes.json) e takes da v2 (edit/cortes2.json): [início no vídeo, take, entrada no take, saída]
const OLD_SEGS: [number, string, number, number][] = [
  [0.0, "IMG_5344", 0.835, 2.6017],
  [1.7667, "IMG_5344", 2.839, 4.339],
  [3.2667, "IMG_5344", 4.583, 5.6497],
  [4.3333, "IMG_5344", 5.906, 7.006],
  [5.4333, "IMG_5344", 7.188, 8.6547],
  [6.9, "IMG_5345", 0.697, 4.697],
  [10.9, "IMG_5345", 4.927, 6.2937],
  [12.2667, "IMG_5345", 6.731, 10.7977],
  [16.3333, "IMG_5346", 0.704, 5.8373],
  [21.4667, "IMG_5347", 0.548, 5.648],
  [26.5667, "IMG_5347", 5.959, 11.059],
  [31.6667, "IMG_5348", 0.737, 4.337],
  [35.2667, "IMG_5348", 4.543, 8.343],
  [39.0667, "IMG_5348", 8.629, 10.529],
  [40.9667, "IMG_5348", 10.752, 14.1187],
  [44.3333, "IMG_5349", 0.835, 6.7683],
  [50.2667, "IMG_5349", 7.088, 12.6213],
  [55.8, "IMG_5350", 1.392, 7.4587],
  [61.8667, "IMG_5350", 7.538, 12.638],
];
const NEW_TAKES: Record<string, [number, number]> = {
  "IMG_5344": [0.0, 0.735],
  "IMG_5345": [8.0333, 0.597],
  "IMG_5346": [18.3, 0.604],
  "IMG_5347": [23.5333, 0.448],
  "IMG_5348": [34.2667, 0.637],
  "IMG_5349": [47.8333, 0.735],
  "IMG_5350": [59.8333, 1.292],
};
// nós da conversão: cada início de frase da v1 cai no mesmo ponto do take na v2 (linear entre eles, sem congelar)
const NK = [...OLD_SEGS.map(([, tk, a]) => NEW_TAKES[tk][0] + (a - NEW_TAKES[tk][1])), SPEECH2];
const OK = [...OLD_SEGS.map(([o]) => o), SPEECH];
const ext = { extrapolateLeft: "extend", extrapolateRight: "extend" } as const;
const toOld = (tn: number) => interpolate(tn, NK, OK, ext);
const toNew = (to: number) => interpolate(to, OK, NK, ext);
const CUTS = OLD_SEGS.map(([o]) => o);

// ── fala (A-roll)
const Aroll: React.FC<{ t: number }> = ({ t }) => {
  let i = 0;
  for (let k = 0; k < CUTS.length; k++) if (CUTS[k] <= t + 1e-4) i = k;
  const a = CUTS[i];
  const b = CUTS[i + 1] ?? SPEECH;
  // v2: plano alterna entre aberto e fechado a cada frase, mas desliza de um para o outro (0,7 s), sem soco
  const zf = (k: number) => (k % 2 ? 1.12 : 1.02);
  const m = interpolate(t, [a, a + 0.7], [0, 1], { ...cl, easing: Easing.inOut(Easing.cubic) });
  let z = (i > 0 ? zf(i - 1) + (zf(i) - zf(i - 1)) * m : zf(0)) + 0.07 * lin(t, a, b);
  const xf = (k: number) => (k % 2 ? 26 : -26); // pan lateral lento, alterna o lado a cada frase
  const x = (i > 0 ? xf(i - 1) + (xf(i) - xf(i - 1)) * m : xf(0)) * (0.4 + 0.6 * lin(t, a, b));
  z += interpolate(t, [0, 0.6], [0.35, 0], { ...cl, easing: OUT });
  return (
    <AbsoluteFill style={{ background: BK, overflow: "hidden" }}>
      <OffthreadVideo
        src={P("aroll2.mp4")}
        muted
        style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", transform: `translateX(${x.toFixed(1)}px) scale(${z.toFixed(4)})`, transformOrigin: "50% 22%" }}
      />
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(0,0,0,0.35) 0%, rgba(0,0,0,0) 16%, rgba(0,0,0,0) 44%, rgba(0,0,0,0.5) 70%, rgba(0,0,0,0.78) 100%)" }} />
    </AbsoluteFill>
  );
};

// ── entradas das telas (nenhuma repete duas vezes seguidas)
type Fin = "slideL" | "fade" | "iris" | "rise" | "doorsV" | "doorsH" | "zoom" | "blinds" | "wipe";
const finStyle = (tin: Fin, e: number): React.CSSProperties => {
  if (tin === "slideL") return { transform: `translateX(${((e - 1) * 1080).toFixed(0)}px)`, boxShadow: "30px 0 80px rgba(0,0,0,0.5)" };
  if (tin === "fade") return { opacity: e, filter: e < 1 ? `blur(${((1 - e) * 20).toFixed(1)}px)` : undefined };
  if (tin === "iris") return { clipPath: `circle(${(e * 120).toFixed(1)}% at 50% 42%)` };
  if (tin === "rise") return { transform: `translateY(${((1 - e) * 1920).toFixed(0)}px)` };
  if (tin === "doorsV") return { clipPath: `inset(0% ${((1 - e) * 50).toFixed(2)}% 0% ${((1 - e) * 50).toFixed(2)}%)` };
  if (tin === "doorsH") return { clipPath: `inset(${((1 - e) * 50).toFixed(2)}% 0% ${((1 - e) * 50).toFixed(2)}% 0%)` };
  if (tin === "blinds") {
    const h = (e * 192).toFixed(1);
    const m = `repeating-linear-gradient(180deg, #000 0px, #000 ${h}px, transparent ${h}px, transparent 192px)`;
    return { WebkitMaskImage: m, maskImage: m };
  }
  if (tin === "wipe") {
    const x = -40 + e * 180;
    return { clipPath: `polygon(0% 0%, ${x.toFixed(1)}% 0%, ${(x - 40).toFixed(1)}% 100%, 0% 100%)` };
  }
  return { opacity: Math.min(1, e * 2), transform: `scale(${(2.0 - 1.0 * e).toFixed(4)})` };
};
const inE = (t: number, a: number) => Easing.bezier(0.33, 0, 0.2, 1)(lin(t, a, a + 0.34));

// câmera das telas: aproxima o tempo todo, contínua (v2: sem soco nas palavras)
const Flat: React.FC<{ t: number; a: number; b: number; bg: string; tin: Fin; hits?: number[]; children: React.ReactNode }> = ({ t, a, b, bg, tin, children }) => {
  if (t < a || t >= b) return null;
  const k = interpolate(t, [a, b], [0, 1], { ...cl, easing: Easing.inOut(Easing.sin) });
  const cam = 0.86 + 0.22 * k;
  const dy = 40 - 80 * k; // sobe devagar enquanto aproxima
  return (
    <AbsoluteFill style={{ background: bg, ...finStyle(tin, inE(t, a)) }}>
      <AbsoluteFill style={{ transform: `translateY(${dy.toFixed(1)}px) scale(${cam.toFixed(4)})`, transformOrigin: "50% 42%" }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

// foto ou vídeo do cliente ocupando o quadro, aproximação lenta
const Shot: React.FC<{ t: number; a: number; b: number; src: string; video?: boolean; tin: Fin; z?: [number, number]; pos?: string; origin?: string; drift?: number }> = ({ t, a, b, src, video, tin, z = [1.04, 1.12], pos = "50% 50%", origin = "50% 40%", drift = 0 }) => {
  if (t < a || t >= b) return null;
  const s = z[0] + (z[1] - z[0]) * lin(t, a, b);
  const dx = drift * (lin(t, a, b) - 0.5);
  const st: React.CSSProperties = { position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", objectPosition: pos };
  return (
    <AbsoluteFill style={{ overflow: "hidden", background: BK, ...finStyle(tin, inE(t, a)) }}>
      <AbsoluteFill style={{ transform: `translateX(${dx.toFixed(1)}px) scale(${s.toFixed(4)})`, transformOrigin: origin }}>
        {video ? (
          <Sequence from={Math.round(toNew(a) * PE_FPS)} layout="none">
            <OffthreadVideo src={P(src)} muted style={st} />
          </Sequence>
        ) : (
          <Img src={P(src)} style={st} />
        )}
      </AbsoluteFill>
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(0,0,0,0.3) 0%, rgba(0,0,0,0) 20%, rgba(0,0,0,0.08) 46%, rgba(0,0,0,0.62) 72%, rgba(0,0,0,0.82) 100%)" }} />
    </AbsoluteFill>
  );
};

// ── lettering (abaixo do rosto, no mesmo eixo)
type Line = { at: number; text: string; kind: "kick" | "block" | "white" | "dark" | "kickDark"; size?: number };
const LineEl: React.FC<{ t: number; l: Line }> = ({ t, l }) => {
  const e = ease(t, l.at, 0.3);
  const vis = t >= l.at ? 1 : 0;
  if (l.kind === "kick" || l.kind === "kickDark")
    return (
      <div style={{ fontFamily: F, fontWeight: 800, fontSize: l.size ?? 40, letterSpacing: "0.16em", color: l.kind === "kick" ? "#FFFFFF" : BK, textTransform: "uppercase", whiteSpace: "nowrap", textShadow: l.kind === "kick" ? SHADOW : "none", opacity: e * vis, transform: `translateY(${((1 - e) * 26).toFixed(1)}px)` }}>
        {l.text}
      </div>
    );
  const s = interpolate(t, [l.at, l.at + 0.22], [1.5, 1], { ...cl, easing: OUT });
  const bg = l.kind === "block" ? R : l.kind === "dark" ? BK : "#FFFFFF";
  const fg = l.kind === "white" ? R : "#FFFFFF";
  return (
    <div
      style={{
        fontFamily: S,
        fontWeight: 900,
        fontSize: l.size ?? 92,
        lineHeight: 1,
        color: fg,
        background: bg,
        padding: "12px 30px 16px",
        borderRadius: 10,
        textTransform: "uppercase",
        whiteSpace: "nowrap",
        boxShadow: "0 14px 34px rgba(0,0,0,0.4)",
        borderBottom: l.kind === "block" ? `5px solid ${GOLD}` : undefined,
        opacity: vis * Math.min(1, e * 3),
        transform: `scale(${s.toFixed(4)})`,
      }}
    >
      {l.text}
    </div>
  );
};
const Lettering: React.FC<{ t: number; a: number; b: number; lines: Line[]; top?: number; badge?: Badge }> = ({ t, a, b, lines, top = 1060, badge }) => {
  if (t < a || t >= b) return null;
  const out = 1 - lin(t, b - 0.12, b);
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap: 16, opacity: out }}>
      {badge && (
        <div style={{ position: "absolute", top: -150, left: 0, right: 0, display: "flex", justifyContent: "center" }}>
          <BadgeDraw t={t} at={a} kind={badge} />
        </div>
      )}
      {lines.map((l, i) => (
        <LineEl key={i} t={t} l={l} />
      ))}
    </div>
  );
};

// v2: selo desenhado a traço (anel + ícone se desenhando), acima do lettering do pastor
type Badge = "pin" | "pray" | "mail" | "group" | "heart" | "touch" | "flame";
const BADGE: Record<Badge, string[]> = {
  pin: ["M24 42 C14 30 10 24 10 18 a14 14 0 0 1 28 0 c0 6-4 12-14 24 Z", "M24 13 a5 5 0 1 1 0 10 a5 5 0 1 1 0-10"],
  pray: ["M23 10 C21 14 18 22 17 28 C16 32 14 35 12 38 L15 42 C19 38 22 33 23 29 Z", "M25 10 C27 14 30 22 31 28 C32 32 34 35 36 38 L33 42 C29 38 26 33 25 29 Z"],
  mail: ["M8 14 H40 V36 H8 Z", "M8 14 L24 27 L40 14"],
  group: ["M24 9 a5 5 0 1 1 0 10 a5 5 0 1 1 0-10", "M14 38 c0-7 4-11 10-11 s10 4 10 11", "M10 16 a4 4 0 1 1 0 8 a4 4 0 1 1 0-8", "M38 16 a4 4 0 1 1 0 8 a4 4 0 1 1 0-8"],
  heart: ["M24 39 C10 29 6 22 9 15 c3-6 11-6 15 1 c4-7 12-7 15-1 c3 7-1 14-15 24 Z"],
  touch: ["M20 26 V12 a3 3 0 0 1 6 0 V24", "M26 22 a3 3 0 0 1 6 1 V26 a3 3 0 0 1 6 1 V32 c0 6-4 10-10 10 h-3 c-4 0-6-2-8-5 L12 30 a3 3 0 0 1 5-3 L20 30"],
  flame: ["M24 42 C14 42 10 35 12 28 C14 22 19 20 19 13 C24 16 27 20 26 26 C29 24 30 21 30 18 C35 23 37 29 35 34 C33 39 29 42 24 42 Z"],
