const BadgeDraw: React.FC<{ t: number; at: number; kind: Badge }> = ({ t, at, kind }) => {
  const r = interpolate(t, [at, at + 0.55], [0, 1], { ...cl, easing: Easing.inOut(Easing.cubic) });
  const d = interpolate(t, [at + 0.2, at + 0.85], [0, 1], { ...cl, easing: Easing.inOut(Easing.cubic) });
  const f = interpolate(t, [at + 0.7, at + 1.0], [0, 1], cl);
  return (
    <svg width={124} height={124} viewBox="0 0 60 60" style={{ filter: "drop-shadow(0 4px 12px rgba(0,0,0,0.55))" }}>
      <circle cx={30} cy={30} r={28} fill={R} opacity={0.92 * f} />
      <circle cx={30} cy={30} r={28} fill="none" stroke={GOLD} strokeWidth={2.4} pathLength={1} strokeDasharray={1} strokeDashoffset={1 - r} transform="rotate(-90 30 30)" />
      <g transform="translate(6 6)">
        {BADGE[kind].map((pth, i) => (
          <path key={i} d={pth} fill="none" stroke="#FFFFFF" strokeWidth={3.2} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - d} />
        ))}
      </g>
    </svg>
  );
};

