// ── pictogramas (traço grosso e redondo)
const stroke = (c: string, w = 3.4) => ({ fill: "none", stroke: c, strokeWidth: w, strokeLinecap: "round" as const, strokeLinejoin: "round" as const });
type Ico = "heart" | "family" | "house" | "group" | "sprout" | "path";
const Icon: React.FC<{ kind: Ico; s: number; color: string }> = ({ kind, s, color }) => (
  <svg width={s} height={s} viewBox="0 0 48 48" {...stroke(color)}>
    {kind === "heart" && <path d="M24 39 C10 29 6 22 9 15 c3-6 11-6 15 1 c4-7 12-7 15-1 c3 7-1 14-15 24 Z" />}
