    )}
    {kind === "sprout" && <path d="M24 42 V22 M24 26 C24 16 16 12 9 13 C9 21 15 26 24 26 M24 22 C24 13 31 8 39 9 C39 17 33 22 24 22 M14 42 H34" />}
    {kind === "path" && <path d="M14 42 C14 32 34 30 34 20 C34 12 24 10 24 6 M10 42 H18 M30 42 H38" />}
  </svg>
