// 1 · "tem algo na sua vida, na sua família, na sua casa" — grafite, três linhas com ícone, uma por palavra
const Row: React.FC<{ t: number; at: number; icon: Ico; word: string }> = ({ t, at, icon, word }) => {
  const e = interpolate(t, [at, at + 0.32], [0, 1], { ...cl, easing: OUT });
  const p = interpolate(t, [at, at + 0.4], [0, 1], { ...cl, easing: BACK });
  return (
    <div style={{ width: 780, display: "flex", alignItems: "center", gap: 40, opacity: t >= at ? Math.min(1, e * 2.5) : 0, transform: `translateX(${((1 - e) * -140).toFixed(1)}px)` }}>
      <div style={{ position: "relative", width: 170, height: 170, borderRadius: 85, background: R, boxShadow: `0 0 0 6px ${GOLD}`, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${(0.5 + 0.5 * p).toFixed(4)})` }}>
        <svg width={214} height={214} viewBox="0 0 100 100" style={{ position: "absolute", left: -22, top: -22, transform: `rotate(${((t - at) * 40).toFixed(1)}deg)` }}>
          <circle cx={50} cy={50} r={47} fill="none" stroke={GOLD} strokeWidth={1.4} strokeDasharray="4 6" opacity={0.8} />
        </svg>
