  const on = interpolate(t, [a, a + 0.45], [0, 1], { ...cl, easing: BACK });
  const off = 1 - lin(t, b - 0.25, b);
  const beat = (t - a) % 1.0;
  const pulse = 1 + 0.06 * Math.sin(Math.PI * Math.min(1, beat / 0.45)) * (beat < 0.45 ? 1 : 0);
  return (
    <div style={{ position: "absolute", left: 0, right: 0, top: 1370, display: "flex", justifyContent: "center", opacity: off }}>
      <div style={{ position: "relative", transform: `scale(${(0.8 * on * pulse).toFixed(4)})`, transformOrigin: "50% 0%" }}>
        <div style={{ position: "absolute", inset: 0, borderRadius: 999, border: `5px solid ${GOLD}`, transform: `scale(${(1 + beat * 0.18).toFixed(3)}, ${(1 + beat * 0.5).toFixed(3)})`, opacity: (1 - beat) * 0.8 }} />
        <div style={{ display: "flex", alignItems: "center", gap: 26, background: R, borderRadius: 999, padding: "20px 44px 22px 52px", boxShadow: "0 16px 40px rgba(0,0,0,0.45), 0 0 0 4px rgba(255,255,255,0.9)" }}>
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
            <div style={{ fontFamily: F, fontWeight: 700, fontSize: 28, letterSpacing: "0.14em", color: "#FFFFFF", textTransform: "uppercase", whiteSpace: "nowrap" }}>Queremos orar por você</div>
            <div style={{ fontFamily: F, fontWeight: 900, fontSize: 56, lineHeight: 1.05, color: "#FFFFFF", textTransform: "uppercase", whiteSpace: "nowrap" }}>Clica aqui agora</div>
          </div>
          <Hand s={70} />
        </div>
      </div>
    </div>
  );
};

